// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

// Interface for MultiVault
interface IMultiVault {
    function getAtomCost() external view returns (uint256);
    function createAtoms(bytes[] calldata data, uint256[] calldata assets) external payable returns (bytes32[] memory);
}

/**
 * @title PublishQuests
 * @author TrustQuests
 * @notice Factory for creating Quest Atoms with unique naming conventions
 * @dev Enforces "questname_starttime_endtime" naming to ensure execution-layer uniqueness
 */
contract PublishQuests is Ownable, ReentrancyGuard {
    
    // ============================================
    // STATE VARIABLES
    // ============================================
    
    /// @notice The Intuition MultiVault contract
    IMultiVault public multiVault;
    
    /// @notice Address that receives protocol fees (if any)
    address public revenueWallet;
    
    // ============================================
    // EVENTS
    // ============================================
    
    event QuestPublished(
        bytes32 indexed atomId,
        string uniqueIdString,
        address indexed creator,
        uint256 timestamp
    );
    
    event MultiVaultUpdated(address indexed oldAddress, address indexed newAddress);
    event RevenueWalletUpdated(address indexed oldAddress, address indexed newAddress);
    
    // ============================================
    // CONSTRUCTOR
    // ============================================
    
    constructor(address _multiVault, address _revenueWallet) {
        require(_multiVault != address(0), "Invalid MultiVault address");
        require(_revenueWallet != address(0), "Invalid Revenue Wallet address");
        
        multiVault = IMultiVault(_multiVault);
        revenueWallet = _revenueWallet;
    }
    
    // ============================================
    // EXTERNAL FUNCTIONS
    // ============================================
    
    /**
     * @notice Create a new Quest Atom with unique naming
     * @param name The display name of the quest
     * @param startTime Start timestamp of the quest
     * @param endTime End timestamp of the quest
     * @return atomId The created Atom ID
     */
    function createQuestAtom(
        string memory name, 
        uint256 startTime, 
        uint256 endTime
    ) external payable nonReentrant returns (bytes32 atomId) {
        // 1. Construct Unique ID String: "name_startTime_endTime"
        string memory uniqueIdString = string(
            abi.encodePacked(
                name,
                "_",
                _toString(startTime),
                "_",
                _toString(endTime)
            )
        );
        
        // 2. Prepare data for MultiVault
        // We add "TrustQuests: " prefix for protocol branding if desired, 
        // or just use the unique string directly. 
        // Based on previous code "TrustQuests Quest: TITLE [ID]" was used.
        // Let's stick to the user's requested unique string as the identity data.
        bytes[] memory data = new bytes[](1);
        data[0] = bytes(uniqueIdString);
        
        // 3. Get Atom Cost
        uint256 atomCost = multiVault.getAtomCost();
        require(msg.value >= atomCost, "Insufficient payment for atom creation");
        
        // 4. Call MultiVault to create atom
        uint256[] memory assets = new uint256[](1);
        assets[0] = atomCost;
        
        bytes32[] memory createdIds = multiVault.createAtoms{value: atomCost}(data, assets);
        atomId = createdIds[0];
        
        // 5. Refund excess payment if any
        uint256 excess = msg.value - atomCost;
        if (excess > 0) {
            (bool success, ) = msg.sender.call{value: excess}("");
            require(success, "Refund failed");
        }
        
        // 6. Emit Event
        emit QuestPublished(atomId, uniqueIdString, msg.sender, block.timestamp);
        
        return atomId;
    }
    
    // ============================================
    // ADMIN FUNCTIONS
    // ============================================
    
    function setMultiVault(address _multiVault) external onlyOwner {
        require(_multiVault != address(0), "Invalid address");
        emit MultiVaultUpdated(address(multiVault), _multiVault);
        multiVault = IMultiVault(_multiVault);
    }
    
    function setRevenueWallet(address _revenueWallet) external onlyOwner {
        require(_revenueWallet != address(0), "Invalid address");
        emit RevenueWalletUpdated(revenueWallet, _revenueWallet);
        revenueWallet = _revenueWallet;
    }
    
    // ============================================
    // INTERNAL HELPER FUNCTIONS
    // ============================================
    
    /**
     * @dev Converts a `uint256` to its ASCII `string` decimal representation.
     */
    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }
}

